1	import path from 'path';
2	import { readMarkdownFiles } from './files';
3	import { processMarkdownFile } from './page';
4	import { generatePageHtml, generateIndexHtml } from './generator';
5	import { PluginManager, PluginContext } from './plugin';
6	import { TemplatePlugin } from './plugins/template.plugin';
7	import { MarkdownPlugin } from './plugins/markdown.plugin';
8	
9	export async function build(contentDir: string, outputDir: string, templateDir?: string, usePlugins = false): Promise<void> {
10	  console.log(`Reading markdown files from: ${contentDir}`);
11	  const files = await readMarkdownFiles(contentDir);
12	
13	  if (files.length === 0) {
14	    console.log('No markdown files found.');
15	    return;
16	  }
17	
18	  console.log(`Found ${files.length} markdown file(s).`);
19	
20	  const context: PluginContext = { contentDir, outputDir, templateDir };
21	  const pluginManager = new PluginManager();
22	
23	  if (usePlugins) {
24	    pluginManager.register(MarkdownPlugin);
25	    pluginManager.register(TemplatePlugin);
26	    await pluginManager.runOnStart(context);
27	    await pluginManager.runBeforeBuild(context);
28	  }
29	
30	  const pages = [];
31	  for (const file of files) {
32	    const page = await processMarkdownFile(file.name, file.content);
33	    pages.push(page);
34	    await generatePageHtml(page, outputDir, templateDir, usePlugins ? pluginManager : undefined);
35	    console.log(`✓ Generated ${page.slug}.html`);
36	  }
37	
38	  await generateIndexHtml(pages, outputDir);
39	  console.log(`✓ Generated index.html`);
40	
41	  if (usePlugins) {
42	    await pluginManager.runAfterBuild(pages, context);
43	    await pluginManager.runOnEnd(context);
44	  }
45	
46	  console.log(`\nBuild complete! Output: ${outputDir}`);
47	}
