1	import { promises as fs } from 'fs';
2	import path from 'path';
3	
4	export interface MarkdownFile {
5	  name: string;
6	  path: string;
7	  content: string;
8	}
9	
10	export async function readMarkdownFiles(contentDir: string): Promise<MarkdownFile[]> {
11	  const files: MarkdownFile[] = [];
12	
13	  try {
14	    const entries = await fs.readdir(contentDir);
15	    for (const entry of entries) {
16	      if (entry.endsWith('.md')) {
17	        const filePath = path.join(contentDir, entry);
18	        const content = await fs.readFile(filePath, 'utf-8');
19	        files.push({
20	          name: entry,
21	          path: filePath,
22	          content
23	        });
24	      }
25	    }
26	  } catch (error) {
27	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
28	      await fs.mkdir(contentDir, { recursive: true });
29	    } else {
30	      throw error;
31	    }
32	  }
33	
34	  return files;
35	}
36	
37	export async function writeFile(filePath: string, content: string): Promise<void> {
38	  const dir = path.dirname(filePath);
39	  await fs.mkdir(dir, { recursive: true });
40	  await fs.writeFile(filePath, content, 'utf-8');
41	}
42	
43	export async function ensureDir(dirPath: string): Promise<void> {
44	  await fs.mkdir(dirPath, { recursive: true });
45	}
