1	import { parseFrontmatter, Frontmatter } from './frontmatter';
2	import { markdownToHtml } from './markdown';
3	
4	export interface PageData {
5	  title: string;
6	  date?: string;
7	  tags?: string[];
8	  html: string;
9	  slug: string;
10	  template?: string;
11	  layout?: string;
12	  [key: string]: unknown;
13	}
14	
15	export async function processMarkdownFile(filename: string, content: string): Promise<PageData> {
16	  const { data, content: markdownContent } = parseFrontmatter(content);
17	  const html = await markdownToHtml(markdownContent);
18	  const slug = filename.replace(/\.md$/, '');
19	
20	  const title = (data.title as string) || slug.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
21	
22	  return {
23	    slug,
24	    title,
25	    date: data.date as string | undefined,
26	    tags: Array.isArray(data.tags) ? data.tags : undefined,
27	    html,
28	    ...data
29	  };
30	}
