1	import path from 'path';
2	import { writeFile } from './files';
3	import { PageData } from './page';
4	import { PluginManager, PluginContext } from './plugin';
5	import { getEngine, loadTemplate, loadLayout, loadPartials } from './template';
6	
7	export async function generatePageHtml(
8	  page: PageData,
9	  outputDir: string,
10	  templateDir?: string,
11	  pluginManager?: PluginManager
12	): Promise<void> {
13	  let html: string;
14	
15	  if (pluginManager) {
16	    const context: PluginContext = { contentDir: '', outputDir, templateDir };
17	    const processedPage = await pluginManager.runOnFile(page, context);
18	    html = processedPage.html;
19	  } else if (templateDir) {
20	    html = await createPageHtmlWithTemplate(page, templateDir);
21	  } else {
22	    html = createPageHtml(page);
23	  }
24	
25	  const filePath = path.join(outputDir, `${page.slug}.html`);
26	  await writeFile(filePath, html);
27	}
28	
29	export async function generateIndexHtml(pages: PageData[], outputDir: string): Promise<void> {
30	  const html = createIndexHtml(pages);
31	  const filePath = path.join(outputDir, 'index.html');
32	  await writeFile(filePath, html);
33	}
34	
35	async function createPageHtmlWithTemplate(page: PageData, templateDir: string): Promise<string> {
36	  await loadPartials(templateDir);
37	  const eng = getEngine();
38	
39	  let html = page.html;
40	
41	  if (page.template) {
42	    const templateContent = await loadTemplate(page.template, templateDir);
43	    html = eng.render(templateContent, { ...page, body: page.html });
44	  }
45	
46	  if (page.layout) {
47	    const layout = await loadLayout(page.layout, templateDir);
48	    html = eng.render(layout, { ...page, body: html });
49	  }
50	
51	  return html;
52	}
53	
54	function createPageHtml(page: PageData): string {
55	  const tagsList = page.tags && Array.isArray(page.tags)
56	    ? `<div class="tags">${page.tags.map(tag => `<span class="tag">${escapeHtml(tag)}</span>`).join('')}</div>`
57	    : '';
58	
59	  const dateHtml = page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : '';
60	
61	  return `<!DOCTYPE html>
62	<html lang="en">
63	<head>
64	  <meta charset="UTF-8">
65	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
66	  <title>${escapeHtml(page.title)}</title>
67	  <style>
68	    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; color: #333; }
69	    h1 { color: #000; margin-bottom: 10px; }
70	    .meta { color: #666; margin-bottom: 20px; border-bottom: 1px solid #eee; padding-bottom: 10px; }
71	    .date { margin: 0; font-size: 0.9em; }
72	    .tags { margin-top: 10px; }
73	    .tag { display: inline-block; background: #f0f0f0; padding: 4px 8px; margin-right: 5px; border-radius: 3px; font-size: 0.85em; }
74	    .content { margin-top: 20px; }
75	    a { color: #0066cc; }
76	    code { background: #f5f5f5; padding: 2px 4px; border-radius: 3px; }
77	    pre { background: #f5f5f5; padding: 10px; border-radius: 3px; overflow-x: auto; }
78	    .back-link { margin-top: 30px; padding-top: 20px; border-top: 1px solid #eee; }
79	  </style>
80	</head>
81	<body>
82	  <article>
83	    <h1>${escapeHtml(page.title)}</h1>
84	    <div class="meta">
85	      ${dateHtml}
86	      ${tagsList}
87	    </div>
88	    <div class="content">
89	      ${page.html}
90	    </div>
91	  </article>
92	  <footer class="back-link">
93	    <a href="index.html">← Back to all pages</a>
94	  </footer>
95	</body>
96	</html>`;
97	}
98	
99	function createIndexHtml(pages: PageData[]): string {
100	  const pagesList = pages
101	    .sort((a, b) => {
102	      if (!a.date || !b.date) return 0;
103	      return new Date(b.date).getTime() - new Date(a.date).getTime();
104	    })
105	    .map(page => `
106	    <li>
107	      <a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.title)}</a>
108	      ${page.date ? `<span class="date"> — ${escapeHtml(page.date)}</span>` : ''}
109	      ${page.tags && Array.isArray(page.tags) ? `<div class="tags">${page.tags.map(tag => `<span class="tag">${escapeHtml(tag)}</span>`).join('')}</div>` : ''}
110	    </li>
111	  `).join('');
112	
113	  return `<!DOCTYPE html>
114	<html lang="en">
115	<head>
116	  <meta charset="UTF-8">
117	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
118	  <title>All Pages</title>
119	  <style>
120	    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; color: #333; }
121	    h1 { color: #000; }
122	    ul { list-style: none; padding: 0; }
123	    li { padding: 10px 0; border-bottom: 1px solid #eee; }
124	    li:last-child { border-bottom: none; }
125	    a { color: #0066cc; text-decoration: none; font-weight: 500; }
126	    a:hover { text-decoration: underline; }
127	    .date { color: #666; font-size: 0.9em; margin-left: 10px; }
128	    .tags { margin-top: 5px; display: flex; flex-wrap: wrap; gap: 5px; }
129	    .tag { display: inline-block; background: #f0f0f0; padding: 4px 8px; border-radius: 3px; font-size: 0.85em; color: #666; }
130	  </style>
131	</head>
132	<body>
133	  <h1>All Pages</h1>
134	  <p>Total: ${pages.length} page${pages.length === 1 ? '' : 's'}</p>
135	  <ul>
136	    ${pagesList}
137	  </ul>
138	</body>
139	</html>`;
140	}
141	
142	function escapeHtml(text: string): string {
143	  const map: { [key: string]: string } = {
144	    '&': '&amp;',
145	    '<': '&lt;',
146	    '>': '&gt;',
147	    '"': '&quot;',
148	    "'": '&#039;'
149	  };
150	  return text.replace(/[&<>"']/g, char => map[char]);
151	}
