1	import { PageData } from './page';
2	
3	export interface PluginContext {
4	  contentDir: string;
5	  outputDir: string;
6	  templateDir?: string;
7	}
8	
9	export interface Plugin {
10	  name: string;
11	  onStart?: (context: PluginContext) => Promise<void>;
12	  beforeBuild?: (context: PluginContext) => Promise<void>;
13	  onFile?: (page: PageData, context: PluginContext) => Promise<PageData>;
14	  afterBuild?: (pages: PageData[], context: PluginContext) => Promise<void>;
15	  onEnd?: (context: PluginContext) => Promise<void>;
16	}
17	
18	export class PluginManager {
19	  private plugins: Plugin[] = [];
20	
21	  register(plugin: Plugin): void {
22	    this.plugins.push(plugin);
23	  }
24	
25	  async runOnStart(context: PluginContext): Promise<void> {
26	    for (const plugin of this.plugins) {
27	      if (plugin.onStart) {
28	        await plugin.onStart(context);
29	      }
30	    }
31	  }
32	
33	  async runBeforeBuild(context: PluginContext): Promise<void> {
34	    for (const plugin of this.plugins) {
35	      if (plugin.beforeBuild) {
36	        await plugin.beforeBuild(context);
37	      }
38	    }
39	  }
40	
41	  async runOnFile(page: PageData, context: PluginContext): Promise<PageData> {
42	    let result = page;
43	
44	    for (const plugin of this.plugins) {
45	      if (plugin.onFile) {
46	        result = await plugin.onFile(result, context);
47	      }
48	    }
49	
50	    return result;
51	  }
52	
53	  async runAfterBuild(pages: PageData[], context: PluginContext): Promise<void> {
54	    for (const plugin of this.plugins) {
55	      if (plugin.afterBuild) {
56	        await plugin.afterBuild(pages, context);
57	      }
58	    }
59	  }
60	
61	  async runOnEnd(context: PluginContext): Promise<void> {
62	    for (const plugin of this.plugins) {
63	      if (plugin.onEnd) {
64	        await plugin.onEnd(context);
65	      }
66	    }
67	  }
68	}
