5	const testDir = path.join(__dirname, '..', '__test_temp__');
6	
7	async function cleanup(): Promise<void> {
8	  try {
9	    await fs.rm(testDir, { recursive: true, force: true });
10	  } catch (e) {
11	    // ignored
12	  }
13	}
14	
15	describe('files', () => {
16	  beforeEach(async () => {
17	    await cleanup();
18	  });
19	
20	  afterEach(async () => {
21	    await cleanup();
22	  });
23	
24	  describe('readMarkdownFiles', () => {
25	    it('should read markdown files from directory', async () => {
26	      const contentDir = path.join(testDir, 'content');
27	      await fs.mkdir(contentDir, { recursive: true });
28	
29	      await fs.writeFile(path.join(contentDir, 'post1.md'), '# Post 1');
30	      await fs.writeFile(path.join(contentDir, 'post2.md'), '# Post 2');
31	      await fs.writeFile(path.join(contentDir, 'other.txt'), 'Not markdown');
32	
33	      const files = await readMarkdownFiles(contentDir);
34	
35	      expect(files).toHaveLength(2);
36	      expect(files.map(f => f.name).sort()).toEqual(['post1.md', 'post2.md']);
37	      expect(files[0].content).toBeDefined();
38	    });
39	
40	    it('should create directory if it does not exist', async () => {
41	      const contentDir = path.join(testDir, 'nonexistent');
42	
43	      const files = await readMarkdownFiles(contentDir);
44	
45	      expect(files).toHaveLength(0);
46	
47	      const exists = await fs.stat(contentDir).then(() => true).catch(() => false);
48	      expect(exists).toBe(true);
49	    });
50	
51	    it('should handle empty directory', async () => {
52	      const contentDir = path.join(testDir, 'empty');
53	      await fs.mkdir(contentDir, { recursive: true });
54	
55	      const files = await readMarkdownFiles(contentDir);
56	
57	      expect(files).toHaveLength(0);
58	    });
59	
