import { promises as fs } from 'fs';
import path from 'path';
import { CacheManager, BuildStats } from './cache';

const testDir = path.join(__dirname, '..', '__test_cache__');

async function cleanup(): Promise<void> {
  try {
    await fs.rm(testDir, { recursive: true, force: true });
  } catch (e) {
    // ignored
  }
}

describe('CacheManager', () => {
  beforeEach(async () => {
    await cleanup();
  });

  afterEach(async () => {
    await cleanup();
  });

  describe('cache file management', () => {
    it('should initialize with empty manifest', () => {
      const manager = new CacheManager(testDir);
      expect(manager).toBeDefined();
    });

    it('should load empty cache when file does not exist', async () => {
      const manager = new CacheManager(testDir);
      await manager.load();
      // Should not throw
    });

    it('should save cache to file', async () => {
      const manager = new CacheManager(testDir);
      manager.updateEntry('test', 'content', '<html>test</html>');
      await manager.save();

      const cacheFile = path.join(testDir, '.ssg-cache.json');
      const exists = await fs.stat(cacheFile).then(() => true).catch(() => false);
      expect(exists).toBe(true);

      const content = await fs.readFile(cacheFile, 'utf-8');
      const data = JSON.parse(content);
      expect(data.entries.test).toBeDefined();
    });

    it('should load existing cache', async () => {
      const cacheDir = path.join(testDir, 'output');
      await fs.mkdir(cacheDir, { recursive: true });

      const cacheData = {
        version: '1',
        entries: {
          'test': {
            sourceHash: 'abc123',
            renderedHtml: '<html>cached</html>',
            timestamp: Date.now()
          }
        }
      };

      await fs.writeFile(
        path.join(cacheDir, '.ssg-cache.json'),
        JSON.stringify(cacheData),
        'utf-8'
      );

      const manager = new CacheManager(cacheDir);
      await manager.load();

      const cached = manager.getCachedHtml('test');
      expect(cached).toBe('<html>cached</html>');
    });
  });

  describe('change detection', () => {
    it('should detect changed source content', async () => {
      const manager = new CacheManager(testDir);
      await manager.load();

      const sourceContent = '# Hello World';
      const renderedHtml = '<h1>Hello World</h1>';

      manager.updateEntry('test', sourceContent, renderedHtml);

      const isChanged = await manager.isPageChanged('test', sourceContent);
      expect(isChanged).toBe(false);

      const newContent = '# Hello World Updated';
      const isChangedAfterUpdate = await manager.isPageChanged('test', newContent);
      expect(isChangedAfterUpdate).toBe(true);
    });

    it('should detect new pages', async () => {
      const manager = new CacheManager(testDir);
      await manager.load();

      const sourceContent = '# New Post';
      const isChanged = await manager.isPageChanged('newpage', sourceContent);
      expect(isChanged).toBe(true);
    });

    it('should detect template changes', async () => {
      const manager = new CacheManager(testDir);
      await manager.load();

      const sourceContent = '# Post';
      const templateContent = '<div>{{body}}</div>';
      const renderedHtml = '<div><h1>Post</h1></div>';

      manager.updateEntry('test', sourceContent, renderedHtml, templateContent);

      const isChanged = await manager.isPageChanged('test', sourceContent, templateContent);
      expect(isChanged).toBe(false);

      const newTemplate = '<div class="post">{{body}}</div>';
      const isChangedAfterTemplate = await manager.isPageChanged('test', sourceContent, newTemplate);
      expect(isChangedAfterTemplate).toBe(true);
    });

    it('should detect layout changes', async () => {
      const manager = new CacheManager(testDir);
      await manager.load();

      const sourceContent = '# Post';
      const layoutContent = '<html>{{body}}</html>';
      const renderedHtml = '<html><h1>Post</h1></html>';

      manager.updateEntry('test', sourceContent, renderedHtml, undefined, layoutContent);

      const isChanged = await manager.isPageChanged('test', sourceContent, undefined, layoutContent);
      expect(isChanged).toBe(false);

      const newLayout = '<html><body>{{body}}</body></html>';
      const isChangedAfterLayout = await manager.isPageChanged('test', sourceContent, undefined, newLayout);
      expect(isChangedAfterLayout).toBe(true);
    });

    it('should detect when template or layout is added', async () => {
      const manager = new CacheManager(testDir);
      await manager.load();

      const sourceContent = '# Post';
      const renderedHtml = '<h1>Post</h1>';

      manager.updateEntry('test', sourceContent, renderedHtml);

      const isChanged = await manager.isPageChanged('test', sourceContent, '<div>{{body}}</div>');
      expect(isChanged).toBe(true);
    });
  });

  describe('cache retrieval', () => {
    it('should retrieve cached HTML', async () => {
      const manager = new CacheManager(testDir);
      const renderedHtml = '<html><h1>Test</h1></html>';

      manager.updateEntry('test', '# Test', renderedHtml);

      const cached = manager.getCachedHtml('test');
      expect(cached).toBe(renderedHtml);
    });

    it('should return undefined for uncached pages', async () => {
      const manager = new CacheManager(testDir);

      const cached = manager.getCachedHtml('nonexistent');
      expect(cached).toBeUndefined();
    });

    it('should handle multiple cached pages', async () => {
      const manager = new CacheManager(testDir);

      manager.updateEntry('post1', '# Post 1', '<h1>Post 1</h1>');
      manager.updateEntry('post2', '# Post 2', '<h1>Post 2</h1>');
      manager.updateEntry('post3', '# Post 3', '<h1>Post 3</h1>');

      expect(manager.getCachedHtml('post1')).toBe('<h1>Post 1</h1>');
      expect(manager.getCachedHtml('post2')).toBe('<h1>Post 2</h1>');
      expect(manager.getCachedHtml('post3')).toBe('<h1>Post 3</h1>');
    });
  });

  describe('build statistics', () => {
    it('should calculate build stats correctly', () => {
      const manager = new CacheManager(testDir);

      manager.recordPageBuildTime('post1', 100);
      manager.recordPageBuildTime('post2', 150);
      manager.recordPageBuildTime('post3', 120);

      const skipped = new Set(['post1', 'post2']);
      const stats = manager.getStats(3, skipped);

      expect(stats.pagesBuilt).toBe(1);
      expect(stats.pagesSkipped).toBe(2);
      expect(stats.totalPages).toBe(3);
      expect(stats.timeSaved).toBeGreaterThan(0);
    });

    it('should report zero time saved when all pages built', () => {
      const manager = new CacheManager(testDir);

      manager.recordPageBuildTime('post1', 100);

      const skipped = new Set<string>();
      const stats = manager.getStats(1, skipped);

      expect(stats.pagesBuilt).toBe(1);
      expect(stats.pagesSkipped).toBe(0);
      expect(stats.timeSaved).toBe(0);
    });

    it('should estimate time saved for skipped pages without recorded time', () => {
      const manager = new CacheManager(testDir);

      const skipped = new Set(['post1', 'post2']);
      const stats = manager.getStats(3, skipped);

      expect(stats.pagesBuilt).toBe(1);
      expect(stats.pagesSkipped).toBe(2);
      expect(stats.timeSaved).toBeGreaterThan(0);
    });
  });

  describe('cache clearing', () => {
    it('should clear all cache entries', () => {
      const manager = new CacheManager(testDir);

      manager.updateEntry('post1', '# Post 1', '<h1>Post 1</h1>');
      manager.updateEntry('post2', '# Post 2', '<h1>Post 2</h1>');

      manager.clear();

      expect(manager.getCachedHtml('post1')).toBeUndefined();
      expect(manager.getCachedHtml('post2')).toBeUndefined();
    });
  });

  describe('hash consistency', () => {
    it('should produce consistent hashes for same content', async () => {
      const manager = new CacheManager(testDir);

      const content = '# Hello World\n\nThis is a test.';
      const sourceContent = content;
      const templateContent = '<div>{{body}}</div>';

      manager.updateEntry('test1', sourceContent, '<p>Test</p>', templateContent);
      await manager.load(); // This should still have the same content

      const isChanged = await manager.isPageChanged('test1', sourceContent, templateContent);
      expect(isChanged).toBe(false);
    });

    it('should detect minimal content changes', async () => {
      const manager = new CacheManager(testDir);

      const originalContent = '# Hello World';
      manager.updateEntry('test', originalContent, '<h1>Hello World</h1>');

      const modifiedContent = '# Hello World ';
      const isChanged = await manager.isPageChanged('test', modifiedContent);
      expect(isChanged).toBe(true);
    });
  });
});

import { promises as fs } from 'fs';
import path from 'path';
import { build } from './build';

const testDir = path.join(__dirname, '..', '__test_incremental__');
const contentDir = path.join(testDir, 'content');
const outputDir = path.join(testDir, 'dist');
const templateDir = path.join(testDir, 'templates');

async function cleanup(): Promise<void> {
  try {
    await fs.rm(testDir, { recursive: true, force: true });
  } catch (e) {
    // ignored
  }
}

async function setupTestContent(): Promise<void> {
  await fs.mkdir(contentDir, { recursive: true });
  await fs.mkdir(templateDir, { recursive: true });

  const post1 = `---
title: Post 1
date: 2024-01-15
---

# Post 1

Content for post 1.`;

  const post2 = `---
title: Post 2
date: 2024-01-16
---

# Post 2

Content for post 2.`;

  await fs.writeFile(path.join(contentDir, 'post1.md'), post1);
  await fs.writeFile(path.join(contentDir, 'post2.md'), post2);
}

describe('Incremental Build', () => {
  beforeEach(async () => {
    await cleanup();
  });

  afterEach(async () => {
    await cleanup();
  });

  describe('basic incremental build', () => {
    it('should perform full build when cache does not exist', async () => {
      await setupTestContent();

      const stats = await build(contentDir, outputDir, templateDir, false, { incremental: true });

      expect(stats).toBeDefined();
      expect(stats?.pagesBuilt).toBe(2);
      expect(stats?.pagesSkipped).toBe(0);
      expect(stats?.totalPages).toBe(2);

      const post1Exists = await fs.stat(path.join(outputDir, 'post1.html')).then(() => true).catch(() => false);
      const post2Exists = await fs.stat(path.join(outputDir, 'post2.html')).then(() => true).catch(() => false);
      const indexExists = await fs.stat(path.join(outputDir, 'index.html')).then(() => true).catch(() => false);

      expect(post1Exists).toBe(true);
      expect(post2Exists).toBe(true);
      expect(indexExists).toBe(true);

      const cacheExists = await fs.stat(path.join(outputDir, '.ssg-cache.json')).then(() => true).catch(() => false);
      expect(cacheExists).toBe(true);
    });

    it('should skip unchanged pages in subsequent builds', async () => {
      await setupTestContent();

      const firstStats = await build(contentDir, outputDir, templateDir, false, { incremental: true });
      expect(firstStats?.pagesBuilt).toBe(2);

      const secondStats = await build(contentDir, outputDir, templateDir, false, { incremental: true });
      expect(secondStats?.pagesBuilt).toBe(0);
      expect(secondStats?.pagesSkipped).toBe(2);
      expect(secondStats?.totalPages).toBe(2);
    });

    it('should rebuild only changed pages', async () => {
      await setupTestContent();

      await build(contentDir, outputDir, templateDir, false, { incremental: true });

      const post1UpdatedContent = `---
title: Post 1 Updated
date: 2024-01-15
---

# Post 1 Updated

Modified content for post 1.`;

      await fs.writeFile(path.join(contentDir, 'post1.md'), post1UpdatedContent);

      const secondStats = await build(contentDir, outputDir, templateDir, false, { incremental: true });
      expect(secondStats?.pagesBuilt).toBe(1);
      expect(secondStats?.pagesSkipped).toBe(1);
      expect(secondStats?.totalPages).toBe(2);

      const post1Content = await fs.readFile(path.join(outputDir, 'post1.html'), 'utf-8');
      expect(post1Content).toContain('Post 1 Updated');
    });
  });

  describe('cache clearing', () => {
    it('should rebuild all pages with --clean flag', async () => {
      await setupTestContent();

      await build(contentDir, outputDir, templateDir, false, { incremental: true });

      const stats = await build(contentDir, outputDir, templateDir, false, { incremental: true, clean: true });
      expect(stats?.pagesBuilt).toBe(2);
      expect(stats?.pagesSkipped).toBe(0);
      expect(stats?.totalPages).toBe(2);
    });
  });

  describe('new and deleted pages', () => {
    it('should detect new pages and build them', async () => {
      await setupTestContent();

      const firstStats = await build(contentDir, outputDir, templateDir, false, { incremental: true });
      expect(firstStats?.pagesBuilt).toBe(2);

      const post3Content = `---
title: Post 3
date: 2024-01-17
---

# Post 3

Content for post 3.`;

      await fs.writeFile(path.join(contentDir, 'post3.md'), post3Content);

      const secondStats = await build(contentDir, outputDir, templateDir, false, { incremental: true });
      expect(secondStats?.pagesBuilt).toBe(1);
      expect(secondStats?.pagesSkipped).toBe(2);
      expect(secondStats?.totalPages).toBe(3);

      const post3Exists = await fs.stat(path.join(outputDir, 'post3.html')).then(() => true).catch(() => false);
      expect(post3Exists).toBe(true);

      const indexContent = await fs.readFile(path.join(outputDir, 'index.html'), 'utf-8');
      expect(indexContent).toContain('Total: 3 pages');
    });

    it('should handle multiple consecutive incremental builds', async () => {
      await setupTestContent();

      const stats1 = await build(contentDir, outputDir, templateDir, false, { incremental: true });
      expect(stats1?.pagesBuilt).toBe(2);
      expect(stats1?.pagesSkipped).toBe(0);

      const stats2 = await build(contentDir, outputDir, templateDir, false, { incremental: true });
      expect(stats2?.pagesBuilt).toBe(0);
      expect(stats2?.pagesSkipped).toBe(2);

      const post1 = `---
title: Post 1 V2
date: 2024-01-15
---

# Post 1 V2

Content version 2.`;

      await fs.writeFile(path.join(contentDir, 'post1.md'), post1);

      const stats3 = await build(contentDir, outputDir, templateDir, false, { incremental: true });
      expect(stats3?.pagesBuilt).toBe(1);
      expect(stats3?.pagesSkipped).toBe(1);

      const stats4 = await build(contentDir, outputDir, templateDir, false, { incremental: true });
      expect(stats4?.pagesBuilt).toBe(0);
      expect(stats4?.pagesSkipped).toBe(2);
    });
  });

  describe('backward compatibility', () => {
    it('should work with non-incremental builds', async () => {
      await setupTestContent();

      const stats = await build(contentDir, outputDir, templateDir, false, { incremental: false });
      expect(stats).toBeUndefined();

      const post1Exists = await fs.stat(path.join(outputDir, 'post1.html')).then(() => true).catch(() => false);
      expect(post1Exists).toBe(true);
    });

    it('should skip incremental flag when not specified', async () => {
      await setupTestContent();

      await build(contentDir, outputDir, templateDir, false);

      const cacheExists = await fs.stat(path.join(outputDir, '.ssg-cache.json')).then(() => true).catch(() => false);
      expect(cacheExists).toBe(false);
    });
  });

  describe('cache file integrity', () => {
    it('should create valid cache manifest', async () => {
      await setupTestContent();

      await build(contentDir, outputDir, templateDir, false, { incremental: true });

      const cacheFile = path.join(outputDir, '.ssg-cache.json');
      const cacheContent = await fs.readFile(cacheFile, 'utf-8');
      const cache = JSON.parse(cacheContent);

      expect(cache.version).toBe('1');
      expect(cache.entries).toBeDefined();
      expect(cache.entries.post1).toBeDefined();
      expect(cache.entries.post2).toBeDefined();
      expect(cache.entries.post1.sourceHash).toBeDefined();
      expect(cache.entries.post1.timestamp).toBeDefined();
    });

    it('should preserve cache across multiple builds', async () => {
      await setupTestContent();

      const stats1 = await build(contentDir, outputDir, templateDir, false, { incremental: true });

      const cacheFile = path.join(outputDir, '.ssg-cache.json');
      const cacheAfterFirst = await fs.readFile(cacheFile, 'utf-8');

      const stats2 = await build(contentDir, outputDir, templateDir, false, { incremental: true });

      const cacheAfterSecond = await fs.readFile(cacheFile, 'utf-8');

      expect(cacheAfterFirst).toBe(cacheAfterSecond);
      expect(stats2?.pagesSkipped).toBe(2);
    });
  });

  describe('build statistics reporting', () => {
    it('should return correct statistics on full build', async () => {
      await setupTestContent();

      const stats = await build(contentDir, outputDir, templateDir, false, { incremental: true });

      expect(stats?.pagesBuilt).toBe(2);
      expect(stats?.pagesSkipped).toBe(0);
      expect(stats?.totalPages).toBe(2);
      expect(stats?.timeSaved).toBeGreaterThanOrEqual(0);
    });

    it('should return correct statistics on incremental build', async () => {
      await setupTestContent();

      await build(contentDir, outputDir, templateDir, false, { incremental: true });

      const stats = await build(contentDir, outputDir, templateDir, false, { incremental: true });

      expect(stats?.pagesBuilt).toBe(0);
      expect(stats?.pagesSkipped).toBe(2);
      expect(stats?.totalPages).toBe(2);
      expect(stats?.timeSaved).toBeGreaterThan(0);
    });
  });
});

